values
('bmlt-biochem-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which enzyme converts glucose to glucose-6-phosphate in most tissues?","translation":"धेरै tissue मा glucose लाई glucose-6-phosphate मा बदल्ने enzyme कुन हो?","options":["Hexokinase","Glucose oxidase","Amylase","Lipase"],"correctIndex":0,"explanation":"Hexokinase phosphorylates glucose using ATP.","explanationNe":"Hexokinase ले ATP प्रयोग गरी glucose phosphorylate गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The main storage form of glucose in humans is:","translation":"मानव शरीरमा glucose को मुख्य storage form कुन हो?","options":["Glycogen","Cellulose","Sucrose","Lactose"],"correctIndex":0,"explanation":"Glycogen is stored mainly in liver and skeletal muscle.","explanationNe":"Glycogen मुख्यतः liver र skeletal muscle मा सञ्चित हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Which test is commonly used to monitor long-term glycemic control?","translation":"दीर्घकालीन blood glucose control हेर्न कुन test प्रयोग हुन्छ?","options":["HbA1c","Serum amylase","Bilirubin","Urea"],"correctIndex":0,"explanation":"HbA1c reflects average glycemia over roughly 2–3 months.","explanationNe":"HbA1c ले करिब २–३ महिनाको औसत glucose देखाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"A fasting plasma glucose diagnostic threshold for diabetes in adults is:","translation":"वयस्कमा diabetes निदानका लागि fasting plasma glucose threshold कुन हो?","options":["≥126 mg/dL","≥90 mg/dL","≥100 mg/dL","≥110 mg/dL"],"correctIndex":0,"explanation":"A fasting plasma glucose of 126 mg/dL or higher, confirmed as appropriate, meets the diagnostic criterion.","explanationNe":"Fasting glucose 126 mg/dL वा बढी भए उचित confirmation सहित diabetes criterion पूरा हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which lipoprotein is commonly called the good cholesterol carrier?","translation":"Good cholesterol carrier भनेर कुन lipoprotein लाई भनिन्छ?","options":["HDL","LDL","VLDL","Chylomicron"],"correctIndex":0,"explanation":"HDL participates in reverse cholesterol transport.","explanationNe":"HDL ले reverse cholesterol transport मा भूमिका खेल्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"The major apolipoprotein of LDL is:","translation":"LDL को मुख्य apolipoprotein कुन हो?","options":["ApoB-100","ApoA-I","ApoC-II","ApoE only"],"correctIndex":0,"explanation":"ApoB-100 is the principal structural apolipoprotein of LDL.","explanationNe":"ApoB-100 LDL को मुख्य structural apolipoprotein हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Which enzyme is most specific for acute pancreatitis?","translation":"Acute pancreatitis का लागि बढी specific enzyme कुन हो?","options":["Lipase","ALT","ALP","CK-MB"],"correctIndex":0,"explanation":"Serum lipase is generally more specific than amylase for acute pancreatitis.","explanationNe":"Acute pancreatitis मा serum lipase amylase भन्दा सामान्यतया बढी specific हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Bilirubin is formed primarily from breakdown of:","translation":"Bilirubin मुख्यतः कुनको breakdown बाट बन्छ?","options":["Heme","Albumin","Glucose","Cholesterol"],"correctIndex":0,"explanation":"Heme catabolism produces biliverdin and then bilirubin.","explanationNe":"Heme catabolism बाट biliverdin हुँदै bilirubin बन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Unconjugated bilirubin is transported in plasma bound to:","translation":"Unconjugated bilirubin plasma मा कुनसँग bound भएर जान्छ?","options":["Albumin","Transferrin","Haptoglobin","Fibrinogen"],"correctIndex":0,"explanation":"Unconjugated bilirubin is poorly water-soluble and travels bound to albumin.","explanationNe":"Unconjugated bilirubin पानीमा कम घुल्ने भएकाले albumin सँग transport हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Which enzyme is typically elevated in cholestasis?","translation":"Cholestasis मा सामान्यतया कुन enzyme बढ्छ?","options":["Alkaline phosphatase","CK","Amylase","Acid phosphatase"],"correctIndex":0,"explanation":"ALP commonly rises in cholestatic or biliary obstruction patterns.","explanationNe":"Cholestasis वा biliary obstruction मा ALP बढ्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"ALT is found predominantly in which organ?","translation":"ALT मुख्यतः कुन अंगमा पाइन्छ?","options":["Liver","Bone","Heart valve","Spleen only"],"correctIndex":0,"explanation":"ALT is relatively liver-specific compared with AST.","explanationNe":"AST को तुलनामा ALT liver का लागि बढी specific हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which renal marker is produced from muscle creatine metabolism?","translation":"Muscle creatine metabolism बाट बन्ने renal marker कुन हो?","options":["Creatinine","Bilirubin","Troponin","Ammonia"],"correctIndex":0,"explanation":"Creatinine is produced at a relatively steady rate from creatine metabolism.","explanationNe":"Creatinine creatine metabolism बाट तुलनात्मक रूपमा स्थिर दरमा बन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Urea is synthesized mainly in the:","translation":"Urea मुख्यतः कहाँ synthesis हुन्छ?","options":["Liver","Kidney cortex","Pancreas","Spleen"],"correctIndex":0,"explanation":"The hepatic urea cycle converts ammonia to urea.","explanationNe":"Liver को urea cycle ले ammonia लाई urea मा बदल्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"A high serum potassium result from a hemolyzed sample may be:","translation":"Hemolyzed sample मा serum potassium बढेको देखिनु के हुन सक्छ?","options":["Pseudohyperkalemia","True hypokalemia","Always diagnostic of renal failure","A normal finding"],"correctIndex":0,"explanation":"Cell lysis releases intracellular potassium and can falsely elevate the result.","explanationNe":"Cell फुट्दा intracellular potassium निस्केर result झूटो बढ्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"The principal extracellular cation is:","translation":"Extracellular fluid को प्रमुख cation कुन हो?","options":["Sodium","Potassium","Magnesium","Calcium"],"correctIndex":0,"explanation":"Sodium is the major cation in extracellular fluid.","explanationNe":"Sodium extracellular fluid को मुख्य cation हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"The principal intracellular cation is:","translation":"Intracellular fluid को प्रमुख cation कुन हो?","options":["Potassium","Sodium","Chloride","Bicarbonate"],"correctIndex":0,"explanation":"Potassium is the major intracellular cation.","explanationNe":"Potassium intracellular fluid को मुख्य cation हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"A common blood gas parameter used to assess metabolic component of acid-base balance is:","translation":"Acid-base balance को metabolic भाग हेर्ने blood gas parameter कुन हो?","options":["Bicarbonate (HCO3−)","PaO2 only","Oxygen saturation only","Carboxyhemoglobin"],"correctIndex":0,"explanation":"Bicarbonate and base excess help assess the metabolic component.","explanationNe":"Bicarbonate र base excess ले metabolic component मूल्यांकन गर्छन्।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Which condition typically causes respiratory acidosis?","translation":"Respiratory acidosis सामान्यतया कुन अवस्थाले गराउँछ?","options":["Hypoventilation with CO2 retention","Excessive vomiting","Diarrhea with bicarbonate loss","Hyperventilation"],"correctIndex":0,"explanation":"Reduced ventilation retains carbon dioxide, increasing carbonic acid.","explanationNe":"Ventilation कम हुँदा CO2 जम्मा भएर carbonic acid बढ्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Which plasma protein contributes most to colloid oncotic pressure?","translation":"Colloid oncotic pressure मा सबैभन्दा बढी योगदान गर्ने plasma protein कुन हो?","options":["Albumin","Globulin","Fibrinogen","Hemoglobin"],"correctIndex":0,"explanation":"Albumin is abundant and exerts much of plasma oncotic pressure.","explanationNe":"Albumin धेरै मात्रामा हुने भएकाले plasma oncotic pressure को ठूलो भाग दिन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Electrophoresis separates serum proteins mainly according to their:","translation":"Electrophoresis ले serum protein मुख्यतः केका आधारमा छुट्याउँछ?","options":["Electrical charge and mobility","Odor","Color only","Boiling point"],"correctIndex":0,"explanation":"Protein migration depends on charge, size/shape, and the applied conditions.","explanationNe":"Protein को migration charge, आकार र प्रयोग गरिएको condition मा निर्भर हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Which vitamin is required for gamma-carboxylation of clotting factors?","translation":"Clotting factor को gamma-carboxylation का लागि कुन vitamin चाहिन्छ?","options":["Vitamin K","Vitamin C","Vitamin B12","Vitamin D"],"correctIndex":0,"explanation":"Vitamin K is needed for functional factors II, VII, IX, and X.","explanationNe":"Vitamin K ले factor II, VII, IX र X लाई functional बनाउन मद्दत गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"The active form of vitamin D is:","translation":"Vitamin D को active form कुन हो?","options":["1,25-dihydroxyvitamin D (calcitriol)","25-hydroxyvitamin D only","Cholecalciferol","Ergocalciferol"],"correctIndex":0,"explanation":"Calcitriol is the hormonally active form of vitamin D.","explanationNe":"Calcitriol vitamin D को hormone-active form हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"Which analyte is commonly measured to assess iron stores?","translation":"Iron store मूल्यांकन गर्न कुन analyte मापन गरिन्छ?","options":["Ferritin","Troponin","Myoglobin","Ceruloplasmin"],"correctIndex":0,"explanation":"Ferritin reflects iron stores, though it can rise with inflammation.","explanationNe":"Ferritin ले iron store देखाउँछ, तर inflammation मा पनि बढ्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Transferrin saturation is calculated using serum iron and:","translation":"Transferrin saturation गणना गर्न serum iron सँग कुन चाहिन्छ?","options":["Total iron-binding capacity (TIBC)","Serum sodium","Serum albumin only","Bilirubin"],"correctIndex":0,"explanation":"Transferrin saturation is serum iron divided by TIBC, multiplied by 100.","explanationNe":"Transferrin saturation = serum iron/TIBC × 100।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Which marker is most associated with myocardial injury and is preferred for diagnosis of acute MI?","translation":"Myocardial injury सँग सम्बन्धित र acute MI निदानमा प्राथमिक marker कुन हो?","options":["Cardiac troponin","Total cholesterol","ALP","Amylase"],"correctIndex":0,"explanation":"Cardiac troponin I or T is the preferred biomarker in suspected myocardial injury.","explanationNe":"Suspected myocardial injury मा cardiac troponin I वा T प्राथमिक biomarker हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"CK-MB is an isoenzyme associated particularly with:","translation":"CK-MB isoenzyme विशेष गरी कुन tissue सँग सम्बन्धित छ?","options":["Cardiac muscle","Liver","Pancreatic acinar cells","Thyroid"],"correctIndex":0,"explanation":"CK-MB is enriched in cardiac muscle but is less specific than troponin.","explanationNe":"CK-MB cardiac muscle मा बढी हुन्छ, तर troponin भन्दा कम specific छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
