('bmlt-biochem-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"Primary hypothyroidism commonly shows which pattern?","translation":"Primary hypothyroidism मा सामान्यतया कुन pattern देखिन्छ?","options":["High TSH with low free T4","Low TSH with high free T4","High TSH with high T3 in all cases","Normal TSH always"],"correctIndex":0,"explanation":"Failure of the thyroid gland lowers T4 and increases pituitary TSH.","explanationNe":"Thyroid gland कमजोर हुँदा T4 घट्छ र pituitary TSH बढ्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
