('bmlt-biochem-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"Which enzyme converts lactate to pyruvate in the reversible reaction?","translation":"Reversible reaction मा lactate लाई pyruvate मा बदल्ने enzyme कुन हो?","options":["Lactate dehydrogenase","Alkaline phosphatase","GGT","Trypsin"],"correctIndex":0,"explanation":"Lactate dehydrogenase catalyzes the lactate–pyruvate reaction.","explanationNe":"Lactate dehydrogenase ले lactate–pyruvate reaction catalyze गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"Which analyte is a useful marker of muscle injury and may rise after strenuous exercise?","translation":"Muscle injury को marker र strenuous exercise पछि बढ्न सक्ने analyte कुन हो?","options":["Creatine kinase (CK)","Bilirubin","TSH","Chloride"],"correctIndex":0,"explanation":"CK is released from muscle and can rise with muscle injury or intense exercise.","explanationNe":"Muscle injury वा कडा exercise पछि CK बढ्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"GGT is often used alongside ALP to help identify an elevated ALP as:","translation":"ALP बढेको अवस्थामा GGT सँगै कुन स्रोत छुट्याउन मद्दत हुन्छ?","options":["Hepatobiliary rather than bone origin","Always bone origin","Always intestinal origin","Never liver-related"],"correctIndex":0,"explanation":"Concurrent GGT elevation supports a hepatobiliary source of raised ALP.","explanationNe":"ALP सँग GGT पनि बढेमा hepatobiliary source सम्भावित हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"Which hormone lowers blood glucose by promoting cellular uptake and storage?","translation":"Cellular uptake र storage बढाएर blood glucose घटाउने hormone कुन हो?","options":["Insulin","Glucagon","Cortisol","Epinephrine"],"correctIndex":0,"explanation":"Insulin promotes glucose uptake in insulin-sensitive tissues and glycogen synthesis.","explanationNe":"Insulin ले insulin-sensitive tissue मा glucose uptake र glycogen synthesis बढाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"C-peptide measurement helps assess:","translation":"C-peptide मापनले के मूल्यांकन गर्न मद्दत गर्छ?","options":["Endogenous insulin secretion","Injected insulin concentration directly","Serum calcium","Thyroid hormone binding"],"correctIndex":0,"explanation":"C-peptide is released with endogenous insulin from proinsulin cleavage.","explanationNe":"Endogenous proinsulin बाट insulin सँगै C-peptide release हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"Which test reflects average glycemia over a shorter period than HbA1c?","translation":"HbA1c भन्दा छोटो अवधिको औसत glycemia देखाउने test कुन हो?","options":["Fructosamine","Serum sodium","Urine ketones only","Total protein"],"correctIndex":0,"explanation":"Fructosamine reflects glycated serum proteins over about 2–3 weeks.","explanationNe":"Fructosamine ले करिब २–३ हप्ताको glycated serum protein देखाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"A markedly increased anion gap is commonly associated with:","translation":"Anion gap धेरै बढ्नु सामान्यतया कुनसँग सम्बन्धित हुन्छ?","options":["Accumulation of unmeasured acids","Pure respiratory alkalosis only","Low albumin always","Normal acid-base status"],"correctIndex":0,"explanation":"Lactate, ketones, and certain toxins can increase the anion gap.","explanationNe":"Lactate, ketone र केही toxin ले anion gap बढाउन सक्छन्।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-026','BMLT','BMLT NHPC Licensing','mock','free',26,'{"question":"Which electrolyte is essential for parathyroid hormone regulation and neuromuscular function?","translation":"Parathyroid hormone regulation र neuromuscular function का लागि आवश्यक electrolyte कुन हो?","options":["Calcium","Bromide","Lithium","Iodine"],"correctIndex":0,"explanation":"Calcium is central to bone, neuromuscular activity and endocrine regulation.","explanationNe":"Calcium हड्डी, neuromuscular activity र endocrine regulation मा महत्त्वपूर्ण छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem-mock-027','BMLT','BMLT NHPC Licensing','mock','free',27,'{"question":"Which biomarker is commonly used to assess pancreatic exocrine injury in acute pancreatitis?","translation":"Acute pancreatitis मा pancreatic exocrine injury मूल्यांकन गर्न कुन biomarker प्रयोग हुन्छ?","options":["Serum lipase","Serum TSH","Serum ferritin","Serum chloride"],"correctIndex":0,"explanation":"Lipase rises in acute pancreatitis and is useful with clinical assessment.","explanationNe":"Acute pancreatitis मा lipase बढ्छ र clinical assessment सँग उपयोगी हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true)
