-- BMLT NHPC Licensing: Clinical Biochemistry bulk batch
-- 25 MCQ practice + 25 separate mock questions (50 total).
-- Educational practice content; not official NHPC past questions.
begin;
on conflict (content_id) do update set
 faculty=excluded.faculty, subject=excluded.subject,
 content_type=excluded.content_type, access_tier=excluded.access_tier,
 display_order=excluded.display_order, content_data=excluded.content_data,
 is_published=excluded.is_published;
commit;

-- Verify import:
select content_type, count(*) as total
from public.learning_content
where faculty='BMLT'
  and subject='BMLT NHPC Licensing'
  and content_data->>'topic'='Clinical Biochemistry'
  and content_id like 'bmlt-biochem-%'
group by content_type
order by content_type;
